session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT sl.*,a.title_snapshot,a.crew_name,a.operating_pattern,s.operating_date FROM operation_switch_lists sl JOIN operation_assignments a ON a.id=sl.assignment_id JOIN operating_sessions s ON s.id=sl.session_id WHERE sl.id=? AND sl.railroad_id=?');$stmt->execute([$id,(int)$railroad['id']]);$list=$stmt->fetch(PDO::FETCH_ASSOC);if(!$list){http_response_code(404);die('Work order not found.');}$pdo->prepare('UPDATE operation_switch_lists SET printed_at=NOW() WHERE id=? AND railroad_id=?')->execute([$id,(int)$railroad['id']]);$stmt=$pdo->prepare('SELECT * FROM operation_switch_list_moves WHERE switch_list_id=? AND railroad_id=? ORDER BY sequence_number');$stmt->execute([$id,(int)$railroad['id']]);$moves=$stmt->fetchAll(PDO::FETCH_ASSOC);$stmt=$pdo->prepare('SELECT e.reporting_marks,e.road_number,e.photo_filename FROM operation_assignment_locomotives al JOIN equipment e ON e.id=al.equipment_id AND e.railroad_id=? WHERE al.assignment_id=? ORDER BY al.position');$stmt->execute([(int)$railroad['id'],(int)$list['assignment_id']]);$locomotives=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<?php include '../includes/header.php';?><title>Print <?=ttHtml($list['switch_list_number'])?></title><link rel="stylesheet" href="../assets/css/operations.css"></head><body class="tt-print-order"><div class="container-fluid py-3"><header class="tt-print-header d-flex justify-content-between"><div><h1><?=ttHtml($list['switch_list_number'])?> — Revision <?=(int)$list['revision_number']?></h1><p><?=ttHtml($list['title_snapshot'].' · '.$list['operating_date'].' · Crew: '.($list['crew_name']?:'Unassigned'))?></p></div><button class="btn btn-primary" onclick="window.print()">Print</button></header><?php if($locomotives):?><section class="tt-assigned-locomotives"><h2>Assigned Locomotives</h2><div class="tt-locomotive-strip"><?php foreach($locomotives as$locomotive):?><?php $locomotiveLabel=trim($locomotive['reporting_marks'].' '.$locomotive['road_number']);?><div class="tt-locomotive"><?php if($url=ttPhotoUrl($locomotive['photo_filename'])):?><img src="<?=ttHtml($url)?>" alt="<?=ttHtml($locomotiveLabel)?>"><?php else:?><span class="tt-no-photo">No Photo</span><?php endif;?><strong><?=ttHtml($locomotiveLabel)?></strong></div><?php endforeach;?></div></section><?php endif;?><table class="table table-bordered tt-work-order-table"><thead><tr><th>Done</th><th>Photo</th><th>Car</th><th>Action</th><th>Instruction</th><th>From</th><th>To</th><th>Actual / Exception</th></tr></thead><tbody><?php foreach($moves as$move):?><?php if($move['action']==='LOCATION'):?><tr class="tt-location-heading"><th colspan="8"><?=ttHtml($move['work_location']?:$move['instruction'])?></th></tr><?php else:?><tr><td><?=$move['equipment_id']?'☐':''?></td><td><?php if($url=ttPhotoUrl($move['photo_filename_snapshot'])):?><img class="tt-car-thumb tt-switch-list-thumb" src="<?=ttHtml($url)?>" alt="<?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?>"><?php endif;?></td><td><?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?></td><td><?=ttHtml($move['action'])?></td><td><?=ttHtml($move['instruction'])?></td><td><?=ttHtml(trim($move['origin_name_snapshot'].' / '.$move['origin_track'],' /'))?></td><td><?=ttHtml(trim($move['destination_name_snapshot'].' / '.$move['destination_track'],' /'))?></td><td></td></tr><?php endif;?><?php endforeach;?></tbody></table></div></body></html>
